for i in range(n):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j and k in adj[i]:
                    triangles.append((i,j,k))
print("Triangles:", triangles)

# Check 4-cycles
quads = []
for a in range(n):
    for b in adj[a]:
        if b > a:
            for c in adj[b]:
                if c != a:
                    for d in adj[c]:
                        if d != b and d > a and d in adj[a]:
                            # Check it's a proper 4-cycle
                            cycle = tuple(sorted([a,b,c,d]))
                            if cycle not in quads:
                                quads.append(cycle)
print("4-cycles (vertex sets):", quads)

